import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const {
    scenePosition = [2.5, 1.6, 0],
    sceneRotation = [0, 0, 0],
    sceneScale = [1, 1, 1],
    imageUrl = '/prism-mock/home/nodes/cta-hero-isolated.png'
  } = config;

  const group = new THREE.Group();
  group.position.set(...scenePosition);
  group.rotation.set(...sceneRotation);
  group.scale.set(...sceneScale);

  // Load texture via cached loader
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Main image plane (aspect ratio 512:320 = 1.6:1)
  const imageGeometry = new THREE.PlaneGeometry(1.6, 1.0);
  const imageMaterial = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true
  });
  const imageMesh = new THREE.Mesh(imageGeometry, imageMaterial);
  group.add(imageMesh);

  // Focus accent edge (glowing border)
  const borderPadding = 0.05;
  const borderGeometry = new THREE.PlaneGeometry(1.6 + borderPadding * 2, 1.0 + borderPadding * 2);
  const borderMaterial = new MeshBasicNodeMaterial({
    color: 0xff2a38,
    transparent: true,
    opacity: 0
  });
  const borderMesh = new THREE.Mesh(borderGeometry, borderMaterial);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // Interaction state
  let hoverTimeline = null;
  let focusTimeline = null;
  const baseY = scenePosition[1];
  let isHovered = false;
  let isFocused = false;

  // Event handlers
  const handlers = {
    onHover: () => {
      if (isHovered) return;
      isHovered = true;
      if (hoverTimeline) hoverTimeline.kill();

      hoverTimeline = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        onComplete: () => { hoverTimeline = null; }
      });
    },

    onUnhover: () => {
      if (!isHovered) return;
      isHovered = false;
      if (hoverTimeline) hoverTimeline.kill();

      hoverTimeline = gsap.to(group.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
        onComplete: () => { hoverTimeline = null; }
      });
    },

    onClick: () => {
      // Press-down effect
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        yoyo: true,
        repeat: 1
      });

      // Emit select event
      if (config.onEvent) {
        config.onEvent('hub-journal.select');
      }
    },

    onFocus: () => {
      if (isFocused) return;
      isFocused = true;
      if (focusTimeline) focusTimeline.kill();

      focusTimeline = gsap.to(borderMaterial, {
        opacity: 1,
        duration: 0.3,
        ease: 'power2.out',
        onComplete: () => { focusTimeline = null; }
      });
    },

    onBlur: () => {
      if (!isFocused) return;
      isFocused = false;
      if (focusTimeline) focusTimeline.kill();

      focusTimeline = gsap.to(borderMaterial, {
        opacity: 0,
        duration: 0.3,
        ease: 'power2.out',
        onComplete: () => { focusTimeline = null; }
      });
    }
  };

  // Cleanup function
  function cleanup() {
    if (hoverTimeline) hoverTimeline.kill();
    if (focusTimeline) focusTimeline.kill();

    imageGeometry.dispose();
    imageMaterial.dispose();
    texture.dispose();

    borderGeometry.dispose();
    borderMaterial.dispose();
  }

  group.userData.handlers = handlers;
  group.userData.cleanup = cleanup;

  return group;
}
